arguments.command:
cd /app; cat > tests/price_test.sh <<'EOF'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
[ "$(bash lib/statement.sh 999)" = "statement member 899" ] || { echo "statement 999"; fail=1; }
exit $fail
EOF
bash scripts/verify.sh; echo "RED exit $?"
sed -i 's/(\$1 \* 90 + 99) \/ 100/$1 * 90 \/ 100/' bin/price bin/quote lib/invoice.sh lib/statement.sh
grep -rn "90 + 99" --exclude-dir=.git . ; grep -rn '\* 90' bin lib
bash scripts/verify.sh; echo "GREEN exit $?"

